llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "(S)-thalidomide absolute oral bioavailability was ~80% in healthy volunteers after capsule vs infusion, supporting high F for a small neutral heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Mephobarbital absolute oral bioavailability was 71-75% in human volunteers after oral vs IV dosing, supporting high F for a lipophilic neutral aromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ondansetron absolute oral bioavailability was 66.1 ± 14.4% in healthy volunteers, with multiple reports of 56-71%, supporting high F despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Fenspiride absolute oral bioavailability was 90% in healthy volunteers after slow-release tablet vs IV, showing near-complete absorption for a small neutral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Primidone oral bioavailability was >90% in humans, with absolute F reported >90%, supporting high F for a small, relatively nonpolar molecule.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence, with high assay-transfer scores, shows high absolute oral bioavailability (≥60-100%) for small, neutral, moderately lipophilic drugs; the query coumarin shares these physicochemical features, and no evidence supports F<20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coumarin itself; potential extensive first-pass metabolism (e.g., CYP2A6-mediated 7-hydroxylation) and lactone hydrolysis are not directly captured by the analogue set.",
    "Most analogues are larger and contain imide/amine functionalities; transfer is based on assay rather than exact structural similarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

